const listLoyaltyCustomerPackages = `-- name: ListLoyaltyCustomerPackages :many
SELECT cp.id, cp.uuid, cp.organization_id, cp.package_id, cp.customer_id, cp.name, cp.price, cp.currency, cp.status, cp.purchased_at, cp.expires_at, cp.payment_method, cp.finance_account_id, cp.finance_transaction_id, cp.cari_entry_id, cp.notes, cp.created_by, cp.cancelled_at, cp.created_at, cp.updated_at, c.uuid AS customer_uuid, c.name AS customer_name, p.uuid AS package_uuid,
       COALESCE((SELECT SUM(cr.total) FROM loyalty_customer_package_credits cr WHERE cr.customer_package_id = cp.id), 0)::bigint AS credits_total,
       COALESCE((SELECT SUM(cr.used) FROM loyalty_customer_package_credits cr WHERE cr.customer_package_id = cp.id), 0)::bigint AS credits_used
FROM loyalty_customer_packages cp
JOIN customers c ON c.id = cp.customer_id
LEFT JOIN loyalty_packages p ON p.id = cp.package_id
WHERE cp.organization_id = $1
  AND ($2::bigint IS NULL OR cp.customer_id = $2)
  AND ($3::text IS NULL OR cp.name ILIKE '%' || $3 || '%' OR c.name ILIKE '%' || $3 || '%')
  AND (
    $4::text IS NULL
    OR ($4 = 'cancelled' AND cp.status = 'cancelled')
    OR ($4 = 'expired' AND cp.status = 'active' AND cp.expires_at IS NOT NULL AND cp.expires_at <= NOW())
    OR ($4 = 'used_up' AND cp.status = 'active' AND (cp.expires_at IS NULL OR cp.expires_at > NOW())
        AND NOT EXISTS (SELECT 1 FROM loyalty_customer_package_credits cr WHERE cr.customer_package_id = cp.id AND cr.used < cr.total))
    OR ($4 = 'active' AND cp.status = 'active' AND (cp.expires_at IS NULL OR cp.expires_at > NOW())
        AND EXISTS (SELECT 1 FROM loyalty_customer_package_credits cr WHERE cr.customer_package_id = cp.id AND cr.used < cr.total))
  )
ORDER BY cp.purchased_at DESC, cp.id DESC
LIMIT $6 OFFSET $5
`

