const listLoyaltySubscriptions = `-- name: ListLoyaltySubscriptions :many
SELECT s.id, s.uuid, s.organization_id, s.plan_id, s.customer_id, s.vehicle_id, s.name, s.price, s.currency, s.period_months, s.uses_per_period, s.start_date, s.paid_through, s.status, s.notes, s.created_by, s.cancelled_at, s.created_at, s.updated_at, c.uuid AS customer_uuid, c.name AS customer_name, c.phone AS customer_phone,
       p.uuid AS plan_uuid, v.uuid AS vehicle_uuid, v.plate AS vehicle_plate
FROM loyalty_subscriptions s
JOIN customers c ON c.id = s.customer_id
LEFT JOIN loyalty_subscription_plans p ON p.id = s.plan_id
LEFT JOIN customer_vehicles v ON v.id = s.vehicle_id
WHERE s.organization_id = $1
  AND ($2::bigint IS NULL OR s.customer_id = $2)
  AND ($3::text IS NULL OR s.name ILIKE '%' || $3 || '%' OR c.name ILIKE '%' || $3 || '%'
       OR v.plate ILIKE '%' || $3 || '%')
  AND (
    $4::text IS NULL
    OR ($4 = 'cancelled' AND s.status = 'cancelled')
    OR ($4 = 'past_due' AND s.status = 'active' AND s.paid_through <= $5::date)
    OR ($4 = 'active' AND s.status = 'active' AND s.paid_through > $5::date)
  )
  AND ($6::date IS NULL OR (s.status = 'active' AND s.paid_through < $6))
ORDER BY
    CASE WHEN $6::date IS NOT NULL THEN s.paid_through END ASC,
    s.created_at DESC, s.id DESC
LIMIT $8 OFFSET $7
`

